javascript(/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    const item = { ...event.context.item.value
    };
    const isChecked = event.payload.value;

    item.selected = isChecked;

    let selectedFeedback = api.state.userFeedback || [];

    if (isChecked) {
        selectedFeedback.push(item);
    } else {
        selectedFeedback = selectedFeedback.filter(
            f => !(f.label === item.label && f.value === item.value)
        );
    }

    return {
        propName: "userFeedback",
        value: selectedFeedback
    };
})

